# ── Modelos Pydantic ──────────────────────────────────────────────────────────
class CompanyData(BaseModel):
    name: str = "Pinturas Pireco SL"
    cif: str = "B75852400"
    address: str = "Calle La Pitera 22B"
    city: str = "Vall de Uxó"
    province: str = "Castellón"
    postal_code: str = "12600"
    phone: str = "623 192 321"
    email: str = "info@pinturaspireco.com"
    iban: str = "ES21 0182 7518 3602 0170 5927"
    swift: str = "BBVAESMMXXX"

class ClientData(BaseModel):
    name: str
    cif: Optional[str] = None
    address: str = ""
    city: str = ""
    province: Optional[str] = None
    postal_code: str = ""

class ItemData(BaseModel):
    description: str
    sub_description: Optional[str] = None
    quantity: Optional[float] = None
    unit: Optional[str] = None
    unit_price: Optional[float] = None
    tag: Optional[str] = None  # int | ext | met | oth

class DocData(BaseModel):
    number: str
    status: str = "sent"
    issue_date: Optional[str] = None
    expiry_date: Optional[str] = None
    due_date: Optional[str] = None
    iva_pct: int = 21
    notes: Optional[str] = None

class TreatmentData(BaseModel):
    name: str
    description: str

class PDFRequest(BaseModel):
    doc_type: str = "budget"  # budget | proforma | invoice
    doc: DocData
    client: ClientData
    items: List[ItemData] = []
    treatments: List[TreatmentData] = []
    company: Optional[CompanyData] = None
    conditions: Optional[List[dict]] = None
    acceptance: Optional[List[str]] = None

# ── Endpoint ──────────────────────────────────────────────────────────────────
@app.post("/generate")
async def generate_pdf(req: PDFRequest):
    try:
        company = req.company or CompanyData()
        conditions = req.conditions or DEFAULT_CONDITIONS
        acceptance = req.acceptance or DEFAULT_ACCEPTANCE

        # Calcular totales
        base = Decimal("0")
        for item in req.items:
            if item.quantity and item.unit_price:
                base += Decimal(str(item.quantity)) * Decimal(str(item.unit_price))
        base = base.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        iva = (base * Decimal(str(req.doc.iva_pct)) / 100).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        total = base + iva

        # Enriquecer items
        items_ctx = []
        for item in req.items:
            ctx = {
                "description": item.description,
                "sub_description": item.sub_description,
                "tag": item.tag,
                "tag_label": TAG_LABELS.get(item.tag or "", ""),
                "qty_fmt": None,
                "price_fmt": None,
                "total_fmt": None,
            }
            if item.quantity and item.unit_price:
                item_total = Decimal(str(item.quantity)) * Decimal(str(item.unit_price))
                ctx["qty_fmt"] = f"{str(item.quantity).rstrip('0').rstrip('.')} {item.unit or ''}".strip()
                ctx["price_fmt"] = fmt_money(item.unit_price)
                ctx["total_fmt"] = fmt_money(item_total)
            items_ctx.append(ctx)

        # Contexto del documento
        doc_ctx = {
            "number": req.doc.number,
            "status": req.doc.status,
            "status_label": STATUS_LABELS.get(req.doc.status, req.doc.status),
            "status_class": STATUS_CLASSES.get(req.doc.status, "status-sent"),
            "issue_date_fmt": fmt_date(req.doc.issue_date),
            "expiry_date_fmt": fmt_date(req.doc.expiry_date),
            "due_date_fmt": fmt_date(req.doc.due_date),
            "iva_pct": req.doc.iva_pct,
            "notes": req.doc.notes,
            "base_amount": fmt_money(base),
            "iva_amount": fmt_money(iva),
            "total_amount": fmt_money(total),
        }

        total_pages = 3 if req.treatments else 2

        # Renderizar
        tmpl = Template(HTML_TEMPLATE)
        html_str = tmpl.render(
            logo_b64=LOGO_B64,
            font_regular=FONT_REGULAR,
            font_medium=FONT_MEDIUM,
            font_semibold=FONT_SEMIBOLD,
            font_bold=FONT_BOLD,
            doc_type=req.doc_type,
            doc_type_label=DOC_LABELS.get(req.doc_type, "Documento"),
            doc=doc_ctx,
            client=req.client,
            items=items_ctx,
            treatments=req.treatments,
            company=company,
            conditions=conditions,
            acceptance=acceptance,
            total_pages=total_pages,
        )

        pdf_bytes = HTML(string=html_str).write_pdf()

        filename = f"{req.doc.number}.pdf"
        return Response(
            content=pdf_bytes,
            media_type="application/pdf",
            headers={"Content-Disposition": f'attachment; filename="{filename}"'}
        )

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/health")
async def health():
    return {"status": "ok", "service": "pireco-pdf"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=int(os.getenv("PORT", 8000)))
